81	        Objects.requireNonNull(pattern, "pattern must not be null");
82	        Objects.requireNonNull(text, "text must not be null");
83	
84	        if (pattern.isEmpty()) {
85	            throw new IllegalArgumentException("pattern must not be empty");
86	        }
87	    }
88	}

