 3	public final class KmpSearchSelfTest {
 4	
 5	    private KmpSearchSelfTest() {
 6	    }
 7	
 8	    public static void main(String[] args) {
 9	        assertEquals(List.of(0, 9, 12), KmpSearch.search("aaba", "aabaacaadaabaaba"), "basic search");
10	        assertEquals(List.of(0, 1, 2), KmpSearch.search("aa", "aaaa"), "overlapping matches");
11	        assertEquals(List.of(), KmpSearch.search("xyz", "aaaa"), "no matches");
12	        assertEquals(List.of(), KmpSearch.search("longer-pattern", "short"), "pattern longer than text");
13	
14	        KmpPattern compiledPattern = KmpPattern.compile("aba");
15	        assertEquals("aba", compiledPattern.value(), "compiled pattern preserves source value");
16	        assertEquals(List.of(0, 2), compiledPattern.findMatchesIn("ababa"), "compiled pattern search");
17	        assertTrue(compiledPattern.occursIn("xxabaxx"), "occursIn should detect matches");
18	        assertFalse(compiledPattern.occursIn("xxxx"), "occursIn should reject missing matches");
19	
20	        assertThrows(IllegalArgumentException.class, () -> KmpPattern.compile(""), "empty pattern rejected");
21	        assertThrows(NullPointerException.class, () -> KmpPattern.compile(null), "null pattern rejected");
22	        assertThrows(NullPointerException.class, () -> compiledPattern.findMatchesIn(null), "null text rejected");
23	    }
